445:                     .Where(t => t.TokenType == TokenType.Indicator && t.SourceIndicatorId.HasValue && indicatorDict.ContainsKey(t.SourceIndicatorId.Value))
446:                     .Select(t => t.SourceIndicatorId.Value)
447:                     .Distinct()
448:                     .ToList() ?? new List<Guid>();
449: 
450:                 dependencies[ind.IndicatorId] = new HashSet<Guid>(deps);
451:             }
452: 
453:             foreach (var kvp in dependencies)
454:             {
455:                 foreach (var parentId in kvp.Value)
456:                 {
457:                     dependents[parentId].Add(kvp.Key);
458:                 }
459:             }
460: 
461:             var currentLevelIds = dependencies.Where(kvp => kvp.Value.Count == 0).Select(kvp => kvp.Key).ToList();
462:             int processedCount = 0;
463: 
464:             while (currentLevelIds.Count > 0)
465:             {
466:                 var currentLevel = new List<Indicator>();
467:                 var nextLevelIds = new List<Guid>();
468: 
469:                 foreach (var id in currentLevelIds)
470:                 {
471:                     currentLevel.Add(indicatorDict[id]);
472:                     processedCount++;
473:                 }
474:                 levels.Add(currentLevel);
475: 
476:                 foreach (var id in currentLevelIds)
477:                 {
478:                     foreach (var depId in dependents[id])
479:                     {
480:                         dependencies[depId].Remove(id);
481:                         if (dependencies[depId].Count == 0)
482:                         {
483:                             nextLevelIds.Add(depId);
484:                         }
485:                     }
486:                 }
487: 
488:                 currentLevelIds = nextLevelIds;
489:             }
490: 
491:             if (processedCount < indicatorList.Count)
492:             {
493:                 var unvisited = indicatorList.Where(i => dependencies[i.IndicatorId].Count > 0).Select(i => i.Code);
494:                 throw new InvalidOperationException($"Circular dependency detected among calculated indicators: {string.Join(", ", unvisited)}");
