563:                         .Distinct()
564:                         .ToListAsync();
565: 
566:                     // get all dates that have been entered (not aggregated) for the child, plus any dates 'above' those
567:                     dates = await db.Data.Where(o => o.EntityId == entityLink.ChildEntityId && !o.Aggregated)
568:                         .Select(o => o.Date)
569:                         .Distinct()
570:                         .ToListAsync();
571:                 }
572: 
573:                 var tokenStackLevels = await GetTokenStacksToCalculateAsync(indicatorIdsToAggregate);
574: 
575:                 // get the dates selected plus the 'parents' of those
576:                 var dateIds = dates.Select(o => o.DateId).ToList();
577:                 foreach (var dateId in dates.Where(o => o.QuarterId.HasValue).Select(o => o.QuarterId.Value).Distinct())
578:                     if (!dateIds.Contains(dateId)) dateIds.Add(dateId);
579:                 foreach (var dateId in dates.Where(o => o.YearId.HasValue).Select(o => o.YearId.Value).Distinct())
580:                     if (!dateIds.Contains(dateId)) dateIds.Add(dateId);
581: 
582:                 // save the entityLink change
583:                 await db.SaveChangesAsync();
584: 
