597:         internal static Stack<TokenStruct> ToPostFixStack(Indicator indicator)
598:         {
599:             var tokens = indicator.Tokens.OrderBy(o => o.TokenNumber);
600: 
601:             // get the tokens from the infix stack
602:             var tempStack = new Stack<Token>(tokens);
603:             var newStack = new Stack<Token>();
604:             while (tempStack.Count > 0) newStack.Push(tempStack.Pop());
605: 
606:             // temporary stacks
607:             var output = new Stack<TokenStruct>();
608:             var operators = new Stack<TokenStruct>();
609: 
610:             while (newStack.Count > 0)
611:             {
612:                 var currentToken = newStack.Pop();
613: 
614:                 // if it's an operator
615:                 if (currentToken.TokenType == TokenType.Operator)
616:                 {
617:                     var associativeness = currentToken.Associativeness;
618:                     var precedence = currentToken.Precedence;
619: 
620:                     // move precedent operators to output
621:                     while (operators.Count > 0 && operators.Peek().TokenType == TokenType.Operator)
622:                     {
623:                         var nextOperator = operators.Peek();
624: 
625:                         if ((associativeness == Associativeness.Left &&
626:                              precedence <= nextOperator.Precedence)
627:                             ||
628:                             (associativeness == Associativeness.Right &&
629:                              precedence < nextOperator.Precedence))
630:                         {
631:                             if (operators.Count == 0) throw new ArgumentException("Invalid formula: missing operator");
632:                             output.Push(operators.Pop());
633:                         }
634:                         else
635:                         {
636:                             break;
637:                         }
638:                     }
639:                     // add to operators
640:                     operators.Push(new TokenStruct
641:                     {
642:                         TokenType = currentToken.TokenType,
643:                         OperatorType = currentToken.OperatorType,
644:                         Precedence = precedence
645:                     });
646:                 }
647:                 // if it's a bracket
648:                 else if (currentToken.TokenType == TokenType.Parenthesis)
649:                 {
650:                     switch (currentToken.ParenthesisType)
651:                     {
652:                         // if it's an opening bracket, add it to operators
653:                         case ParenthesisType.Open:
654:                             operators.Push(new TokenStruct
655:                             {
656:                                 TokenType = TokenType.Parenthesis,
657:                                 ParenthesisType = ParenthesisType.Open
658:                             });
659:                             break;
660:                         // if it's a closing bracket
661:                         case ParenthesisType.Close:
662:                             // shift operators in between opening to output 
663:                             while (operators.Count > 0)
664:                             {
665:                                 var nextOperator = operators.Peek();
666:                                 if (nextOperator.TokenType == TokenType.Parenthesis
667:                                     && nextOperator.ParenthesisType == ParenthesisType.Open) break;
668:                                 if (operators.Count == 0) throw new ArgumentException("Invalid formula: missing parenthesis");
669:                                 output.Push(operators.Pop());
670:                             }
671:                             // add to operators
672:                             if (operators.Count == 0) throw new ArgumentException("Invalid formula: missing parenthesis");
673:                             operators.Pop();
674:                             break;
675:                     }
676:                 }
677:                 // if it's numeric (or equivalent), add to output
678:                 else if (currentToken.TokenType == TokenType.Number || currentToken.TokenType == TokenType.Indicator)
679:                 {
680:                     output.Push(new TokenStruct
681:                     {
682:                         TokenType = currentToken.TokenType,
683:                         Number = currentToken.Number,
684:                         ConvertNullToZero = currentToken.ConvertNullToZero,
685:                         IndicatorId = currentToken.SourceIndicatorId,
686:                         RequiresSubmit = currentToken.SourceIndicator?.RequiresSubmit ?? currentToken.Indicator?.RequiresSubmit ?? false
687:                     });
688:                 }
689:                 else
690:                 {
691:                     throw new ArgumentException("Invalid formula: invalid token type");
692:                 }
693:             }
694: 
695:             // for all remaining operators, move to output
696:             while (operators.Count > 0)
697:             {
698:                 output.Push(operators.Pop());
699:             }
700: 
701:             // reverse the stack
702:             var reversedStack = new Stack<TokenStruct>();
703:             while (output.Count > 0)
704:             {
705:                 var token = output.Pop();
706:                 if (token.TokenType == TokenType.Parenthesis) throw new ArgumentException("Invalid formula: missing parenthesis");
707:                 reversedStack.Push(token);
708:             }
709: 
710:             // return the reversed postfix stack
711:             var arr = new TokenStruct[reversedStack.Count];
712:             reversedStack.CopyTo(arr, 0);
713:             Array.Reverse(arr);
714:             return new Stack<TokenStruct>(arr);
715:         }
