                    .Select(o => o.Id)
                    .SingleAsync();

                db.Entry(new IdentityUserRole<Guid> { UserId = user.Id, RoleId = adminRoleId }).State = EntityState.Added;
                await db.SaveChangesAsync();

                AdminUserId = user.Id;
            }
        }

        public Task DisposeAsync() => Task.CompletedTask;
    }
